// Closed chain week, same rule as data/pipelines/pipeline.py previous_chain_week_bounds.
// America/Bogota is UTC-5 all year (no daylight saving). Headquarters is Medellín.
// America/New_York is not used: US daylight saving would shift Monday 07:00
// relative to the Bogotá chain-week boundary for part of the year.

// BRASALAND_FN chainWeekBounds
function chainWeekBounds(now) {
  const date = now instanceof Date ? new Date(now.getTime()) : new Date(now);
  if (Number.isNaN(date.getTime())) {
    throw new Error('chainWeekBounds requires a valid date');
  }
  const BOGOTA_OFFSET_MS = 5 * 60 * 60 * 1000;
  const bogota = new Date(date.getTime() - BOGOTA_OFFSET_MS);
  const weekday = bogota.getUTCDay();
  const daysSinceMonday = (weekday + 6) % 7;
  const todayUtc = Date.UTC(
    bogota.getUTCFullYear(),
    bogota.getUTCMonth(),
    bogota.getUTCDate(),
  );
  const thisMonday = todayUtc - daysSinceMonday * 86400000;
  const isoDate = (utcMs) => {
    const d = new Date(utcMs);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    return y + '-' + m + '-' + day;
  };
  return {
    week_start: isoDate(thisMonday - 7 * 86400000),
    week_end: isoDate(thisMonday),
    timezone: 'America/Bogota',
  };
}
// BRASALAND_FN_END chainWeekBounds

const input = $input.first().json || {};
const base = String(input.api_base_url || 'http://host.docker.internal:8000').replace(/\/$/, '');
const bounds = chainWeekBounds(new Date());
return [
  {
    json: {
      api_base_url: base,
      week_start: bounds.week_start,
      week_end: bounds.week_end,
      timezone: bounds.timezone,
    },
  },
];

// BRASALAND_FN formatLeadershipReport
const LOCATION_NAMES = {
  'co-med-centro': 'Medellín Centro',
  'co-med-elpoblado': 'Medellín El Poblado',
  'co-bog-chapinero': 'Bogotá Chapinero',
  'co-bog-norte': 'Bogotá Norte',
  'co-cali-norte': 'Cali Norte',
  'co-barranquilla': 'Barranquilla',
  'co-cartagena': 'Cartagena',
  'co-pereira': 'Pereira',
  'us-mia-brickell': 'Miami Brickell',
  'us-mia-downtown': 'Miami Downtown',
  'us-orlando': 'Orlando',
  'us-tampa': 'Tampa',
  'us-ftlauderdale': 'Fort Lauderdale',
  'us-jacksonville': 'Jacksonville',
};

function formatMoney(amount, currency) {
  const n = Number(amount);
  const code = currency || '';
  if (!Number.isFinite(n)) return (code ? code + ' ' : '') + '—';
  const sign = n < 0 ? '-' : '';
  const fixed = Math.abs(n).toFixed(2);
  const parts = fixed.split('.');
  const whole = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (code ? code + ' ' : '') + sign + whole + '.' + parts[1];
}

function formatRatio(value) {
  const ratio = Number(value);
  if (!Number.isFinite(ratio)) return '—';
  return (ratio * 100).toFixed(2) + '%';
}

function sumField(rows, key) {
  return rows.reduce((acc, row) => acc + (Number(row[key]) || 0), 0);
}

function csvEscape(value) {
  const text = value == null ? '' : String(value);
  if (/[",\n]/.test(text)) return '"' + text.replace(/"/g, '""') + '"';
  return text;
}

function locationName(locationId) {
  return LOCATION_NAMES[locationId] || locationId || 'Unknown location';
}

function marketSection(title, rows, currency) {
  const lines = [];
  lines.push(title + ' — ' + rows.length + ' location' + (rows.length === 1 ? '' : 's'));
  if (!rows.length) {
    lines.push('No location rows for this currency.');
    return lines.join('\n');
  }
  if (currency) {
    lines.push('Purchase cost: ' + formatMoney(sumField(rows, 'total_purchase_cost'), currency));
    lines.push('Waste cost: ' + formatMoney(sumField(rows, 'total_waste_cost'), currency));
    lines.push('Stockout frequency: ' + sumField(rows, 'stockout_events_count'));
    lines.push('Price alert frequency: ' + sumField(rows, 'price_alert_events_count'));
  }
  const sorted = rows.slice().sort((a, b) => locationName(a.location_id).localeCompare(locationName(b.location_id)));
  sorted.forEach((row) => {
    const rowCurrency = currency || row.currency || '';
    lines.push('');
    lines.push(locationName(row.location_id) + ' (' + (row.country || 'Unknown country') + ')');
    lines.push('Purchase cost: ' + formatMoney(row.total_purchase_cost, rowCurrency));
    lines.push('Waste cost: ' + formatMoney(row.total_waste_cost, rowCurrency));
    lines.push('Waste ratio: ' + formatRatio(row.waste_ratio));
    lines.push('Stockout frequency: ' + (row.stockout_events_count == null ? 0 : row.stockout_events_count));
    lines.push('Price alert frequency: ' + (row.price_alert_events_count == null ? 0 : row.price_alert_events_count));
  });
  return lines.join('\n');
}

function formatLeadershipReport(payload, weekEnd) {
  const body = payload && typeof payload === 'object' ? payload : {};
  const locations = Array.isArray(body.locations) ? body.locations : [];
  const weekStart = body.week_start || 'unknown';
  const end = weekEnd || 'unknown';
  const cop = locations.filter((row) => row && row.currency === 'COP');
  const usd = locations.filter((row) => row && row.currency === 'USD');
  const other = locations.filter((row) => row && row.currency !== 'COP' && row.currency !== 'USD');
  const header = [
    'Brasaland Monday leadership report',
    'Audience: Mariana Restrepo (Executive), Felipe Guerrero (Restaurant Operations), Lucía Fernández (Procurement)',
    'Chain week: ' + weekStart + ' through ' + end + ' (end exclusive)',
    'Timezone: America/Bogota',
    'COP and USD are reported separately. This report does not convert between currencies.',
    'Locations in this report: ' + locations.length,
  ];
  if (!locations.length) {
    header.push('No per-location rows were returned for this chain week.');
  }
  const sections = [
    header.join('\n'),
    '',
    marketSection('Colombia (COP)', cop, 'COP'),
    '',
    marketSection('Florida (USD)', usd, 'USD'),
  ];
  if (other.length) {
    sections.push('');
    sections.push(marketSection('Other currencies', other, null));
  }
  const reportText = sections.join('\n');
  const csvHeader = [
    'week_start',
    'week_end_exclusive',
    'location_id',
    'location_name',
    'country',
    'currency',
    'purchase_cost',
    'waste_cost',
    'waste_ratio',
    'stockout_frequency',
    'price_alert_frequency',
  ];
  const csvRows = locations.map((row) => [
    weekStart,
    end,
    row.location_id,
    locationName(row.location_id),
    row.country,
    row.currency,
    row.total_purchase_cost,
    row.total_waste_cost,
    row.waste_ratio,
    row.stockout_events_count,
    row.price_alert_events_count,
  ].map(csvEscape).join(','));
  const csv = [csvHeader.join(',')].concat(csvRows).join('\n') + '\n';
  let slackText = reportText;
  if (slackText.length > 3500) {
    slackText = slackText.slice(0, 3500) + '\n… truncated. Full report is in the email and CSV.';
  }
  return {
    week_start: weekStart,
    week_end: end,
    subject: 'Brasaland weekly location performance ' + weekStart + ' (COP and USD)',
    report_text: reportText,
    slack_text: slackText,
    csv_filename: 'brasaland-weekly-' + weekStart + '.csv',
    csv: csv,
    location_count: locations.length,
    cop_location_count: cop.length,
    usd_location_count: usd.length,
    cop_purchase_cost: sumField(cop, 'total_purchase_cost'),
    usd_purchase_cost: sumField(usd, 'total_purchase_cost'),
  };
}
// BRASALAND_FN_END formatLeadershipReport

function utf8Base64(text) {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(text, 'utf8').toString('base64');
  }
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  bytes.forEach((b) => {
    binary += String.fromCharCode(b);
  });
  return btoa(binary);
}

const payload = $input.first().json;
let weekEnd = '';
try {
  weekEnd = $('Resolve last chain week').first().json.week_end || '';
} catch (error) {
  weekEnd = '';
}
const report = formatLeadershipReport(payload, weekEnd);
return [
  {
    json: {
      week_start: report.week_start,
      week_end: report.week_end,
      subject: report.subject,
      report_text: report.report_text,
      slack_text: report.slack_text,
      csv_filename: report.csv_filename,
      location_count: report.location_count,
      cop_location_count: report.cop_location_count,
      usd_location_count: report.usd_location_count,
      cop_purchase_cost: report.cop_purchase_cost,
      usd_purchase_cost: report.usd_purchase_cost,
    },
    binary: {
      data: {
        data: utf8Base64(report.csv),
        mimeType: 'text/csv',
        fileName: report.csv_filename,
        fileExtension: 'csv',
      },
    },
  },
];

function utf8Base64(text) {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(text, 'utf8').toString('base64');
  }
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  bytes.forEach((b) => {
    binary += String.fromCharCode(b);
  });
  return btoa(binary);
}

const item = $input.first().json || {};
let message = '';
if (item.error && typeof item.error === 'object') {
  message = item.error.message || item.error.description || '';
  if (!message) message = JSON.stringify(item.error);
} else if (typeof item.error === 'string') {
  message = item.error;
} else if (typeof item['error.message'] === 'string') {
  message = item['error.message'];
} else if (typeof item.message === 'string' && item.message) {
  message = item.message;
} else {
  message = 'Weekly leadership report failed before a delivery step.';
}
message = String(message).replace(/password[=:][^\s,}]+/gi, 'password=[redacted]');
let weekStart = 'unknown';
try {
  weekStart = $('Resolve last chain week').first().json.week_start || 'unknown';
} catch (error) {
  weekStart = 'unknown';
}
const text = [
  'Brasaland Monday leadership report FAILED',
  'Audience: Mariana Restrepo (Executive), Felipe Guerrero (Restaurant Operations), Lucía Fernández (Procurement)',
  'Chain week start: ' + weekStart,
  'Timezone: America/Bogota',
  'Failure: ' + message,
].join('\n');
const outputFilename = 'brasaland-weekly-failure.txt';
return [
  {
    json: {
      subject: 'FAILED: Brasaland weekly location performance ' + weekStart,
      report_text: text,
      slack_text: text,
      output_filename: outputFilename,
      week_start: weekStart,
    },
    binary: {
      data: {
        data: utf8Base64(text + '\n'),
        mimeType: 'text/plain',
        fileName: outputFilename,
        fileExtension: 'txt',
      },
    },
  },
];
